      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class ScalableQualityManager : MonoBehaviour
{
    [Header("Configurações de Resolução Dinâmica")]
    [SerializeField] private float targetFrameRate = 60.0f;
    [SerializeField] private float minRenderScale = 0.70f;
    [SerializeField] private float maxRenderScale = 1.0f;

    [Header("Ajustes de Sombras e Iluminação")]
    [SerializeField] private Light mainDirectionalLight;

    private float currentScale = 1.0f;

    private void Awake()
    {
        Application.targetFrameRate = Mathf.RoundToInt(targetFrameRate);
        QualitySettings.vSyncCount = 0;
        ApplyGpuOptimizations();
    }

    private void Update()
    {
        AdjustRenderScaleDynamically();
    }

    private void ApplyGpuOptimizations()
    {
        QualitySettings.shadowDistance = 40f;
        QualitySettings.shadowCascades = 2;
        QualitySettings.shadowResolution = ShadowResolution.Medium;

        if (mainDirectionalLight != null)
        {
            mainDirectionalLight.shadowResolution = LightShadowResolution.Medium;
        }
    }

    private void AdjustRenderScaleDynamically()
    {
        float currentFps = 1.0f / Mathf.Max(Time.unscaledDeltaTime, 0.0001f);
        if (currentFps < targetFrameRate - 5.0f && currentScale > minRenderScale)
        {
            currentScale = Mathf.Clamp(currentScale - 0.05f * Time.unscaledDeltaTime, minRenderScale, maxRenderScale);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
        else if (currentFps >= targetFrameRate && currentScale < maxRenderScale)
        {
            currentScale = Mathf.Clamp(currentScale + 0.02f * Time.unscaledDeltaTime, minRenderScale, maxRenderScale);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) está demorando quase o dobro do tempo permitido (32.76ms em vez de 16.7ms) para desenhar cada quadro na tela. Para resolver isso, reduzimos o custo do cálculo de sombras e ajustamos a resolução de renderização de forma dinâmica. Em vez de calcular cada pixel na resolução nativa quando o jogo fica pesado, reduzimos levemente a escala interna da imagem e depois esticamos para a tela, economizando milhões de cálculos da placa sem que o jogador perceba perda drástica de qualidade visual."
    },
    {
      "tipo": "DrawCalls",
      "causa_raiz": "O número de Draw Calls atingiu pico de 2797 chamadas, superando o limite tolerado de 2579 para o hardware alvo, gerando overhead na comunicação entre a CPU e o driver gráfico.",
      "codigo_refatorado": "using UnityEngine;

[RequireComponent(typeof(MeshRenderer))]
public class GPUInstancingEnabler : MonoBehaviour
{
    private static MaterialPropertyBlock propertyBlock;
    private MeshRenderer meshRenderer;

    private void Awake()
    {
        meshRenderer = GetComponent<MeshRenderer>();
        if (propertyBlock == null)
        {
            propertyBlock = new MaterialPropertyBlock();
        }

        if (meshRenderer.sharedMaterial != null)
        {
            meshRenderer.sharedMaterial.enableInstancing = true;
        }
    }

    public void SetColor(Color color)
    {
        propertyBlock.SetColor("_BaseColor", color);
        meshRenderer.SetPropertyBlock(propertyBlock);
    }
}",
      "explicacao_didatica": "Toda vez que a CPU manda a GPU desenhar um objeto individual, gasta-se tempo com um 'Draw Call'. Ao ativar GPU Instancing e usar MaterialPropertyBlock, a Unity agrupa dezenas ou centenas de objetos idênticos (como árvores, caixas ou pedras) em uma única instrução de desenho, reduzindo drasticamente a quantidade de comandos enviados."
    }
  ],
  "dicas_level_design": "1. Occlusion Culling: Configure e asse (Bake) o Occlusion Culling na aba Rendering > Occlusion Culling para evitar desenhar cômodos e geometrias escondidas atrás de paredes. 2. Estática e Batching: Marque todos os objetos imutáveis como 'Batching Static' no Inspector para permitir o agrupamento automático de malhas estáticas. 3. Texture Atlasing: Agrupe texturas de múltiplos props decorativos em um único Atlas de texturas para que compartilhem o mesmo material, unificando os Draw Calls. 4. LOD Groups: Implemente níveis de detalhe (LOD) nos assets mais complexos, reduzindo malhas e desligando sombras nos níveis mais distantes. 5. Limitação de Luzes em Tempo Real: Converta iluminação secundária e de preenchimento para Lightmaps estáticos (Baked Light) e limite luzes dinâmicas pontuais com sombras habilitadas a no máximo 1 ou 2 por sala."
}

